           radial-gradient(circle at top left, rgba(79, 107, 237, 0.18), transparent 30%),
           radial-gradient(circle at top right, rgba(98, 204, 198, 0.18), transparent 28%),
           var(--bg);
         min-height: 100vh;
         line-height: 1.5;
       }

