         font-size: 1.1rem;
         font-weight: 800;
         transition: transform 0.2s ease, background-color 0.2s ease;
       }

       .question button[aria-expanded="true"]::after {
         content: "−";
         background: rgba(79, 107, 237, 0.16);
       }

       .details {
         padding: 0 1.25rem 1.25rem;
         color: var(--muted);
       }

       .details p {
         margin: 0;
       }

       .details p + p {
         margin-top: 0.75rem;
       }

       .details ul {
         margin: 0.9rem 0 0;
