         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         padding: 0.45rem 0.8rem;
         border-radius: 999px;
         background: var(--surface-soft);
         color: var(--accent-strong);
         font-weight: 700;
         font-size: 0.875rem;
       }

