         margin: 0;
         max-width: 60ch;
         color: var(--muted);
         font-size: 1.05rem;
       }

       .faq-list {
         display: grid;
         gap: 1rem;
       }

       .example {
         background: rgba(255, 255, 255, 0.92);
         border: 1px solid var(--border);
         border-radius: var(--radius-lg);
         box-shadow: 0 12px 30px rgba(21, 32, 51, 0.06);
         overflow: clip;
       }

       .question {
         margin: 0;
       }

       .question button {
         appearance: none;
         border: 0;
         width: 100%;
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         padding: 1.25rem 1.25rem;
         background: transparent;
         color: var(--text);
         text-align: left;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
       }

       .question button:hover {
         background: rgba(79, 107, 237, 0.05);
       }

       .question button:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: -3px;
       }

       .question button::after {
         content: "+";
         flex: 0 0 auto;
         width: 2rem;
         height: 2rem;
         border-radius: 999px;
         display: grid;
         place-items: center;
         color: var(--accent-strong);
         background: var(--surface-soft);
         font-size: 1.1rem;
         font-weight: 800;
         transition: transform 0.2s ease, background-color 0.2s ease;
       }

       .question button[aria-expanded="true"]::after {
         content: "−";
         background: rgba(79, 107, 237, 0.16);
       }

       .details {
         padding: 0 1.25rem 1.25rem;
         color: var(--muted);
       }

       .js .details {
         display: none;
       }

       .details p {
         margin: 0;
       }

       .details p + p {
         margin-top: 0.75rem;
       }

       .details ul {
         margin: 0.9rem 0 0;
         padding-left: 1.2rem;
       }

       .details li + li {
         margin-top: 0.35rem;
       }

       @media (max-width: 640px) {
         main {
           width: min(100% - 1rem, 920px);
           padding-top: 3.5rem;
         }

         .hero,
         .example {
           border-radius: 20px;
         }

         .question button,
         .details {
           padding-left: 1rem;
           padding-right: 1rem;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         html {
           scroll-behavior: auto;
         }

